{
  "version": "schemaxis.readiness/1",
  "routes": {
    "schemaxis.whispercpp/1": {
      "guide": "docs/whispercpp.md",
      "context": {
        "purpose": "Transcribe a local PCM16 mono 16 kHz speech recording offline into checked millisecond segments, plain text, SRT and WebVTT. Optional caption review flags cue duration and density by fixed editorial thresholds, and an optional segmentation target asks whisper.cpp for shorter word-aware cues. Output is for human review.",
        "assumptions": "Absolute local WAV and ggml model paths, lowercase SHA-256 model pin, English or one explicit lowercase code from the 100 whisper.cpp 1.9.5 language codes (membership does not certify that the model is multilingual or recognises that language); latest stable whisper.cpp 1.9.5 whisper-cli executable.",
        "constraints": "PCM16 mono 16000 Hz, at most 600 seconds and 32MiB audio; model at most 4GiB; 2000 segments, 262144 characters; one CPU thread. No download, prompt, translation, diarisation, VAD, language detection or authored native flags; the only native option is the optional maxSegmentLength (16 to 200 code points, mapped to -ml N -sow), a target that long words and unspaced scripts can exceed, with experimental token-level cue timing. Accuracy is not certified. Caption review thresholds are editorial defaults, not standards, and are not authored.",
        "inspection": "Reopen captured audio and native JSON with strict closed parsing; independently check hashes, finite integral-millisecond timestamps, ordering, non-overlap and audio duration, then regenerate text/SRT/WebVTT byte-for-byte. Native SRT is compared with native JSON. The optional caption review is rebuilt from the checked segments and must match byte-for-byte after strict member and type checks. With maxSegmentLength, the argv must carry exactly the authored -ml N -sow, and segments.json records the target, enforced false and the host-counted cues over it; over-target cues are published, not refused.",
        "recovery": "INVALID_AUDIO_DATA: export PCM16 mono 16000 Hz WAV. AUDIO_RESOURCE_LIMIT: split audio. AUDIO_HASH_MISMATCH/MODEL_HASH_MISMATCH: restore the pinned bytes or update the pin deliberately. MODEL_CHANGED: do not modify the model during a run. TRANSCRIPT_EMPTY: no speech segments, nothing published. TRANSCRIPT_TIMING/TRANSCRIPT_INVALID: native output violated the contract (including a blank-looking or non-text cue); inspect native.json at the reported cue, then use cleaner audio or another pinned model. If maxSegmentLength was set, retry with it omitted or larger. INVALID_LANGUAGE at $.language: use one lowercase code from the schema enum (default en); full names, uppercase, auto and aliases are refused before any file is read. INVALID_ARGUMENT at $.arguments.maxSegmentLength: use a whole number from 16 to 200 or omit it. UNSUPPORTED_NATIVE_VERSION: configure whisper.cpp 1.9.5. VERIFICATION_FAILED on caption-review.json: the report differs from independent recomputation or exists without (or is missing despite) captionReview; rerun from the declared input."
      },
      "examples": [
        {
          "id": "baseline",
          "reference": "examples/schemaxis/whispercpp-jfk.json"
        },
        {
          "id": "excerpt",
          "reference": "examples/schemaxis/whispercpp-excerpt.json"
        },
        {
          "id": "caption-review",
          "reference": "examples/schemaxis/whispercpp-caption-review.json"
        },
        {
          "id": "short-cues",
          "reference": "examples/schemaxis/whispercpp-short-cues.json"
        },
        {
          "id": "relative-invalid",
          "reference": "examples/schemaxis/whispercpp-relative-invalid.json",
          "expect": "invalid",
          "fault": "INVALID_AUDIO_SOURCE",
          "schemaValid": true
        },
        {
          "id": "hash-invalid",
          "reference": "examples/schemaxis/whispercpp-hash-invalid.json",
          "expect": "invalid",
          "fault": "INVALID_SHA256",
          "schemaValid": true
        },
        {
          "id": "invalid-language",
          "reference": "examples/schemaxis/whispercpp-invalid-language.json",
          "expect": "invalid",
          "fault": "INVALID_LANGUAGE",
          "schemaValid": false
        }
      ],
      "conformance": [
        "tests/unit/test_whispercpp.py"
      ],
      "acceptance": [
        "tools/qualify_whispercpp.py"
      ],
      "profiles": {
        "workflow": {
          "scope": "Isolated transcription jobs support source-byte reuse invalidation and verified file artifacts.",
          "references": [
            "docs/whispercpp.md",
            "tools/qualify_whispercpp.py"
          ]
        },
        "composition": {
          "scope": "Shared document references and finite studies resolve before native transcription.",
          "references": [
            "docs/whispercpp.md",
            "tools/qualify_whispercpp.py"
          ]
        }
      },
      "development": {
        "api": [
          "https://github.com/ggml-org/whisper.cpp/tree/v1.9.5/examples/cli",
          "https://github.com/ggml-org/whisper.cpp/releases/tag/v1.9.5"
        ],
        "lifecycle": {
          "timeout": "One total deadline covers capture, model hashing, version, dependency trace, transcription and verification; CPU 3600s, address space 16GiB, file 16MiB per native process.",
          "cancellation": "Cancellation and deadline are checked before capture, before model hashing, after native stages and before publication; shared tracked process-group cancellation terminates owned native jobs.",
          "logs": "Authored/effective plans, captured audio, model/runtime identities, trusted launchers, input bindings, submissions/stdout/stderr, native JSON/SRT and four publications retained (five with captionReview enabled).",
          "verification": "Strict closed JSON, model/audio/runtime hash binding, integral millisecond monotonic nonoverlapping segments inside audio duration, byte-exact regenerated text/SRT/WebVTT, exact membership. Accuracy is not verified. The optional caption review report is recomputed from the checked segments and compared exactly. With maxSegmentLength the segmentation member (target, enforced false, cue and over-target counts) is rebuilt from the checked segments and compared exactly; the cue length is never a pass/fail check."
        },
        "data": [
          {
            "id": "speech",
            "direction": "input",
            "kind": "file",
            "format": "PCM16 WAV",
            "traits": {
              "channels": 1,
              "sampleRate": 16000,
              "maxSeconds": 600
            },
            "losses": [
              "No resampling, channel conversion or compressed audio; metadata chunks are not certified or stripped."
            ],
            "scope": "Captured canonical RIFF PCM16 mono 16000 Hz, optionally pinned by SHA-256."
          },
          {
            "id": "segments",
            "direction": "output",
            "kind": "text",
            "format": "schemaxis.whispercpp.segments/1 JSON",
            "traits": {
              "timeUnit": "millisecond",
              "accuracyCertified": false
            },
            "losses": [
              "No word timing, confidence or speaker labels; recognition accuracy is not certified.",
              "With maxSegmentLength the cue boundaries are native experimental token-level timing and the target is not a guaranteed maximum; both are observed, not certified."
            ],
            "scope": "Closed segment evidence and review limits; with maxSegmentLength also the segmentation member."
          },
          {
            "id": "transcript",
            "direction": "output",
            "kind": "text",
            "format": "UTF-8 text",
            "traits": {
              "linePerSegment": true
            },
            "losses": [
              "Text is native recognition output with surrounding spaces removed."
            ],
            "scope": "Generated from checked segments."
          },
          {
            "id": "captions",
            "direction": "output",
            "kind": "file",
            "format": "SRT and WebVTT",
            "traits": {
              "timeUnit": "millisecond",
              "encoding": "UTF-8"
            },
            "losses": [
              "Cue line-breaking, styling and readability are not produced or certified; the optional segmentation target only asks whisper.cpp for shorter cues."
            ],
            "scope": "Generated byte-for-byte from checked segments."
          },
          {
            "id": "caption-review",
            "direction": "output",
            "kind": "text",
            "format": "schemaxis.whispercpp.caption-review/1 JSON",
            "traits": {
              "unit": "millisecond and Unicode code point",
              "optional": true,
              "passCertified": false
            },
            "losses": [
              "Fixed editorial flags only; not a standard, accessibility or readability certification, and not grapheme or display-width aware."
            ],
            "scope": "Optional per-cue duration, code point count and rate with short-duration, long-duration and dense-text flags, derived from checked segments."
          }
        ],
        "inspection": [
          {
            "panel": "text",
            "scope": "Inspect segments.json, transcript.txt and the two caption files. With captionReview, also inspect caption-review.json.",
            "limits": "No playback, editing or accuracy review; listen to the audio and correct text externally."
          }
        ],
        "authoring": {
          "model": "document",
          "example": "baseline",
          "reuse": "Edit JSON paths and pins, plan and run; audio/model byte changes invalidate workflow reuse."
        },
        "features": {
          "workflow": {
            "status": "supported",
            "scope": "Isolated verified transcription jobs and file artifacts."
          },
          "composition": {
            "status": "supported",
            "scope": "Common references and finite studies resolve before native transcription."
          },
          "reusable-inputs": {
            "status": "supported",
            "scope": "Audio and model byte digests invalidate stale reuse."
          },
          "source-authoring": {
            "status": "supported",
            "scope": "Shared JSON editing and undo."
          },
          "property-authoring": {
            "status": "supported",
            "scope": "Shared pointer editing of paths, pins and language."
          },
          "native-inspection": {
            "status": "unsupported",
            "scope": "The bounded serial offline transcription route does not implement native-inspection."
