          },
          "native-save": {
            "status": "unsupported",
            "scope": "The bounded serial offline transcription route does not implement native-save."
          },
          "conversion": {
            "status": "unsupported",
            "scope": "The bounded serial offline transcription route does not implement conversion."
          }
        },
