    "schemaxis.whispercpp.correct/1": {
      "guide": "docs/whispercpp.md",
      "context": {
        "purpose": "Apply authored per-cue human text corrections, with a declared review status and note, to one retained whisper.cpp machine segments.json and publish a reviewed timed-text document, transcript text, SRT, WebVTT and an exact correction ledger. Host-only: whisper-cli is never launched.",
